<?php
declare(strict_types=1);
require __DIR__.'/integration_support.php';
use Athar\Engagement\CampaignService;
use Athar\Http\ApiError;
use Athar\Infrastructure\LocalSchedule;
$checks=0;
function campaign_check(bool $ok,string $label): void {global $checks;$checks++;if(!$ok)throw new RuntimeException('FAIL: '.$label);}
function campaign_reject(callable $call,int $status,string $label): void {try{$call();}catch(ApiError $e){campaign_check($e->status===$status,$label.' status '.$e->status);return;}campaign_check(false,$label);}
isolated_database(static function(PDO $db):void {
    foreach(['owner','admin','user','user','user','user'] as $i=>$role)$db->prepare("INSERT INTO users(email,username,display_name,password_hash,role,email_verified_at,email_marketing_opt_in,preferences_json) VALUES (?,?,?,'unused',?,UTC_TIMESTAMP(),?,?)")->execute(['campaign'.$i.'@example.invalid','campaign'.$i,'Fixture '.$i,$role,$i>=2?1:0,$i===3?'{}':'{"language":"en"}']);
    $owner=['id'=>1,'role'=>'owner','session_version'=>1];$admin=['id'=>2,'role'=>'admin','session_version'=>1];
    $db->exec("INSERT INTO engagement_channel_preferences(user_id,locale,email_campaign_opt_in,push_campaign_opt_in) VALUES (3,'ar',1,1),(4,'ar',1,1),(5,'en',0,0)");
    $db->exec("UPDATE users SET suspended_at=UTC_TIMESTAMP() WHERE id=6");
    $service=new CampaignService($db,static fn($channel)=>true);
    $base=['name'=>'Campaign fixture','channel'=>'email','title_ar'=>'عنوان تجريبي','body_ar'=>'نص اختباري غير ديني','title_en'=>'Fixture title','body_en'=>'Fixture body','deep_link'=>'/lessons?lesson=1'];
    $draft=$service->createDraft($admin,$base);$id=$draft['id'];
    campaign_check($draft['status']==='draft'&&$draft['revision']===1,'draft only, revision1');
    campaign_check((int)$db->query('SELECT COUNT(*) FROM engagement_campaign_recipients')->fetchColumn()===0,'save never queues recipients');
    $preview=$service->preview($owner,$id);
    campaign_check($preview['audience']['email']['eligible_count']===2,'verified unsuspended consent only, legacy opt-in fallback');
    campaign_check(!str_contains(json_encode($preview),'campaign2@example.invalid'),'preview excludes recipient addresses');
    $prod=new CampaignService($db);
    campaign_check($prod->preview($owner,$id)['dependencies']['email']==='email_transport_not_ready','production readiness cannot be enabled by fixture closure');
    foreach([['title_ar'=>[]],['body_en'=>true],['deep_link'=>'//evil.invalid'],['deep_link'=>'/account/export'],['image_url'=>'https://' . 'user:password' . '@example.invalid/a'],['scheduled_at'=>'tomorrow'],['scheduled_at'=>'2026-02-30T12:00'],['scheduled_at'=>'2026-03-08T02:30','schedule_timezone'=>'America/New_York'],['scheduled_at'=>'2026-11-01T01:30','schedule_timezone'=>'America/New_York'],['schedule_timezone'=>'+02:00'],['ttl_seconds'=>0],['min_frequency_hours'=>0],['respect_quiet_hours'=>1],['worship_history'=>true]] as $bad)campaign_reject(fn()=>$service->createDraft($owner,array_replace($base,$bad)),422,'strict draft validation');
    campaign_check(LocalSchedule::utc('2026-11-01T01:30','America/New_York','-04:00')==='2026-11-01 05:30:00','fold explicit offset retained');
    campaign_check(LocalSchedule::utc('2026-11-01T01:30','America/New_York','-05:00')==='2026-11-01 06:30:00','fold second explicit offset retained');
    $updated=$service->updateDraft($admin,$id,$base+['expected_revision'=>1]);
    campaign_check($updated['revision']===2,'creator CAS edit');
    campaign_reject(fn()=>$service->updateDraft($owner,$id,$base+['expected_revision'=>1]),409,'stale revision rejected');
    campaign_reject(fn()=>$service->confirmAndSchedule($admin,$id,2,'CONFIRM '.$id),403,'only owner launches');
    campaign_reject(fn()=>$service->confirmAndSchedule($owner,$id,2,'yes'),422,'explicit phrase required');
    $db->exec("CREATE TRIGGER fixture_campaign_audit BEFORE INSERT ON audit_logs FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='fixture audit failure'");
    $before=(int)$db->query('SELECT COUNT(*) FROM engagement_campaigns')->fetchColumn();
    try{$service->createDraft($admin,$base);campaign_check(false,'audit failure expected');}catch(PDOException $e){}
    campaign_check((int)$db->query('SELECT COUNT(*) FROM engagement_campaigns')->fetchColumn()===$before,'draft insert and event roll back with audit');
    try{$service->confirmAndSchedule($owner,$id,2,'CONFIRM '.$id);campaign_check(false,'confirm audit failure expected');}catch(PDOException $e){}
    campaign_check((int)$db->query('SELECT COUNT(*) FROM engagement_campaign_recipients')->fetchColumn()===0&&$service->detail($owner,$id)['status']==='draft','snapshot and status roll back with failed audit');
    $db->exec('DROP TRIGGER fixture_campaign_audit');
    $scheduled=$service->confirmAndSchedule($owner,$id,2,'CONFIRM '.$id);
    campaign_check($scheduled['delivery_counts']['queued']===2&&$scheduled['status']==='scheduled','owner confirmation snapshots eligible channels');
    $rows=$db->query('SELECT user_id,locale,payload_json FROM engagement_campaign_recipients ORDER BY user_id')->fetchAll();
    campaign_check($rows[0]['locale']==='en'&&$rows[1]['locale']==='ar','profile locale or explicit fallback selects payload');
    campaign_check(json_decode($rows[0]['payload_json'],true)['title']==='Fixture title','localized immutable payload snapshot');
    campaign_reject(fn()=>$service->confirmAndSchedule($owner,$id,2,'CONFIRM '.$id),409,'duplicate launch creates no deliveries');
    campaign_check((int)$db->query('SELECT COUNT(*) FROM engagement_campaign_recipients')->fetchColumn()===2,'idempotent launch effect');
    $cancel=$service->cancel($admin,$id,3);
    campaign_check($cancel['status']==='cancelled'&&$cancel['delivery_counts']['cancelled']===2,'creator cancellation retires queued snapshot');
    $both=$service->createDraft($admin,array_replace($base,['channel'=>'push_email']));
    $missing=new CampaignService($db,static fn($channel)=>$channel==='email');
    campaign_reject(fn()=>$missing->confirmAndSchedule($owner,$both['id'],1,'CONFIRM '.$both['id']),409,'combined channels launch atomically');
    campaign_check($service->detail($owner,$both['id'])['delivery_counts']['total']===0,'missing push readiness leaves email unqueued');
    $follow=$service->createDraft($admin,$base+['audience_type'=>'lesson_reminders','audience_ref_id'=>1]);
    campaign_check($service->preview($owner,$follow['id'])['dependencies']['email']==='lesson_reminders_not_ready','canonical future subscription dependency gates without duplicate table');
    $push=$service->createDraft($admin,array_replace($base,['channel'=>'push']));
    $service->confirmAndSchedule($owner,$push['id'],1,'CONFIRM '.$push['id']);
    $db->exec('UPDATE engagement_channel_preferences SET push_campaign_opt_in=0 WHERE user_id=4');
    $claims=$service->claimPushBatch();
    campaign_check(count($claims)===1&&(int)$claims[0]['user_id']===3,'claim rechecks revoked consent before reserving');
    $claim=$claims[0];
    campaign_check($service->detail($owner,$push['id'])['delivery_counts']['skipped']===1,'revoked snapshot skipped without payload delivery');
    $db->prepare("UPDATE engagement_campaign_recipients SET locked_at=DATE_SUB(UTC_TIMESTAMP(),INTERVAL 20 MINUTE) WHERE id=?")->execute([$claim['id']]);
    $service->recoverQueue();$again=$service->claimPushBatch();
    campaign_check(count($again)===1&&(int)$again[0]['attempt_count']===2,'stale claim recovered with increased attempt fence');
    campaign_reject(fn()=>$service->completePush((int)$claim['id'],1),409,'late previous worker cannot complete reclaimed delivery');
    campaign_reject(fn()=>$service->failPush((int)$claim['id'],1,'provider_unavailable'),409,'late previous worker cannot requeue reclaimed delivery');
    $service->failPush((int)$claim['id'],2,'provider echoed secret fixture');
    $retry=$db->query('SELECT * FROM engagement_campaign_recipients WHERE id='.(int)$claim['id'])->fetch();
    campaign_check($retry['status']==='queued'&&$retry['last_error_code']==='delivery_failed'&&strtotime($retry['next_attempt_at'].' UTC')>=time()+115,'bounded exponential retry and operational-only error');
    $db->prepare('UPDATE engagement_campaign_recipients SET next_attempt_at=UTC_TIMESTAMP() WHERE id=?')->execute([$claim['id']]);
    $again=$service->claimPushBatch();$service->completePush((int)$claim['id'],3);
    campaign_check($service->detail($owner,$push['id'])['status']==='completed','provider completion reconciles aggregate campaign');
    $limited=$service->createDraft($admin,array_replace($base,['channel'=>'push','ttl_seconds'=>60]));
    $limited=$service->confirmAndSchedule($owner,$limited['id'],1,'CONFIRM '.$limited['id']);
    campaign_check($limited['status']==='completed'&&$limited['delivery_counts']['skipped']===1,'frequency beyond TTL is explicit skip and closes all-skipped campaign');
    $db->prepare("INSERT INTO engagement_campaign_events(campaign_id,event_type,summary_json) VALUES (?,'recipient@example.invalid',?)")->execute([$push['id'],'{"email":"private@example.invalid","queued":1}']);
    $analytics=json_encode($service->detail($owner,$push['id']));
    campaign_check(!str_contains($analytics,'private@example.invalid')&&!str_contains($analytics,'recipient@example.invalid'),'history allowlists aggregate operational metadata');
    campaign_check($prod->claimPushBatch()===[],'production worker cannot claim without actual campaign dispatcher');
    $db->exec("UPDATE users SET role='user' WHERE id=2");
    campaign_reject(fn()=>$service->createDraft($admin,$base),403,'stale actor role cannot author campaigns');
});
echo "PASS: {$checks} campaign draft/consent/snapshot/CAS/atomicity/readiness assertions; no provider send.\n";
